"""The bundled demo phones are generated by tools/make_demo_phones.py.

If someone edits the generator (or a demo file by hand) without regenerating,
this fails, so the demo, the docs and the tests can't silently disagree.
"""

import importlib.util
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent


def _load_generator():
    spec = importlib.util.spec_from_file_location("make_demo_phones", ROOT / "tools" / "make_demo_phones.py")
    module = importlib.util.module_from_spec(spec)
    sys.modules[spec.name] = module  # dataclasses looks the module up by name
    spec.loader.exec_module(module)
    return module


def _tree(directory: Path) -> dict[str, str]:
    return {p.relative_to(directory).as_posix(): p.read_text(encoding="utf-8") for p in sorted(directory.rglob("*")) if p.is_file()}


def test_committed_demo_data_matches_generator(tmp_path, demo_dir):
    generator = _load_generator()
    generator.main(["--out", str(tmp_path)])
    for name in ("messy", "clean"):
        assert _tree(tmp_path / name) == _tree(demo_dir / name), f"{name} demo drifted; rerun tools/make_demo_phones.py"


def test_demo_data_is_clearly_synthetic(demo_dir):
    text = "\n".join(_tree(demo_dir / "messy").values()) + "\n".join(_tree(demo_dir / "clean").values())
    assert "DemoCorp" in text
    assert "@" not in text  # nothing email-shaped, so nothing that could be a real person's account
